begin
wwv_flow_imp_shared.create_search_config(
 p_id=>wwv_flow_imp.id(2198523431254919514)
,p_label=>'Employees'
,p_static_id=>'employees'
,p_search_type=>'TEXT_MANUAL'
,p_query_type=>'SQL'
,p_query_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select employee_id,',
'       first_name,',
'       last_name,',
'       first_name || '' '' || last_name as name,',
'       email,',
'       user_id,',
'       country,',
'       country_code,',
'       geographic_region,',
'       city,',
'       career_level,',
'       job_title,',
'       cost_center_id,',
'       manager_id,',
'       org_size,',
'       direct_reports,',
'       phone_country_code,',
'       phone_number,',
'       profile,',
'       tags,',
'       permalink,',
'       to_char( systimestamp at time zone timezone, ''HH24:MI'' ) as current_local_time,',
'       timezone',
'  from eba_srch_txt_employees',
''))
,p_oratext_index_column_name=>'LAST_NAME'
,p_oratext_function_type=>'CUSTOM'
,p_oratext_function=>'eba_search_text_helper.get_name_search_query'
