,p_subtitle_column_name=>'CITY'
,p_description_column_name=>'JOB_TITLE'
,p_custom_01_column_name=>'PHONE_NUMBER'
,p_link_target_type=>'REDIRECT_PAGE'
,p_link_target=>'f?p=&APP_ID.:4:&APP_SESSION.::&DEBUG.::P4_EMPLOYEE_ID:&EMPLOYEE_ID.'
,p_icon_source_type=>'INITIALS'
,p_default_row_html_expr=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<article class="a-ResultsItem u-flex u-align-items-center u-gap-4 &RESULT_CSS_CLASSES!ATTR.">',
